package com.example.home_api.web;
import jakarta.servlet.ServletException;import jakarta.servlet.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.AuthenticationException;import org.springframework.security.web.authentication.AuthenticationFailureHandler;import org.springframework.stereotype.Component;import java.io.IOException;
@Component public class LoginFailureHandler implements AuthenticationFailureHandler {private final JdbcTemplate jdbc;public LoginFailureHandler(JdbcTemplate jdbc){this.jdbc=jdbc;}@Override public void onAuthenticationFailure(HttpServletRequest req,HttpServletResponse res,AuthenticationException ex)throws IOException,ServletException{String id=req.getParameter("username");Integer limit=setting("login_failure_limit",5),minutes=setting("account_lock_minutes",30);jdbc.update("UPDATE \"user\" SET login_failure_count=login_failure_count+1,locked_until=CASE WHEN login_failure_count+1>=? THEN CURRENT_TIMESTAMP+(? * INTERVAL '1 minute') ELSE locked_until END,update_date=CURRENT_TIMESTAMP WHERE user_id=?",limit,minutes,id);res.sendRedirect("/login?error");}private int setting(String key,int fallback){try{return Integer.parseInt(jdbc.queryForObject("SELECT value FROM system_setting WHERE key=?",String.class,key));}catch(Exception e){return fallback;}}}
